        this.speedControl.value = Math.min(maxSpeed, 1.5); // Limita a velocidade de voz
        if (this.speakingControlMode === 'slowDown') {
            // Acelera o vídeo, mas nunca acima do teto configurado
            this.video.playbackRate = Math.min(this.video.playbackRate + 0.1, videoMaxRate);
        }
    } else { // Adiantamento (Precisamos desacelerar)
        this.speedControl.value = 1.0; // Ou um valor baixo, dependendo da intenção
        if (this.speakingControlMode === 'slowDown') {
            // Desacelera o vídeo, mas nunca abaixo do chão
            this.video.playbackRate = Math.max(this.video.playbackRate - 0.1, videoMinRate);
        }
    }

    // Garante que o vídeo nunca seja manipulado se não estiver em 'slowDown' e estiver dentro do alvo
    if (this.speakingControlMode !== 'slowDown' && Math.abs(timeDifference) > 500) {
        this.video.playbackRate = 1.0; 
    }

    this.updateRangeValue('speed');
}
```

## Versão 3: Foco em Transição Suave (Easing)

Esta versão utiliza uma lógica de interpolação para que a mudança de velocidade não seja abrupta, mas sim gradual (como um efeito *ease-out*).

```javascript
adjustSynchronization_V3_SmoothTransition(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const nextSpeechTime = this.speechQueue[0].startTime;
    const timeDifference = nextSpeechTime - currentTime;
    const deltaSeconds = Math.abs(timeDifference) / 1000;

    let targetSpeed = this.userConfiguredSpeed;
    let targetVideoRate = 1.0;

    if (deltaSeconds < 0.5) {
        // OK, mantém o padrão
    } else if (timeDifference < 0) { // Atraso -> Acelerar
        targetSpeed = parseFloat(this.maxSpeedControl.value);
        // Aplica uma aceleração suave baseada no desvio
        targetVideoRate = Math.min(1.0 + (deltaSeconds * 0.1), 1.8);
    } else { // Adiantamento -> Desacelerar
        targetSpeed = 1.1; 
        // Aplica uma desaceleração suave
        targetVideoRate = Math.max(1.0 - (deltaSeconds * 0.1), 0.6);
    }

    // Interpolação (Slerp/Lerp simplificado para este exemplo)
    // Faz a mudança de estado acontecer lentamente, em vez de instantaneamente.
    const smoothFactor = 0.1; // 10% da mudança por frame/chamada

    this.speedControl.value = this.speedControl.value + (targetSpeed - this.speedControl.value) * smoothFactor;
    this.video.playbackRate = this.video.playbackRate + (targetVideoRate - this.video.playbackRate) * smoothFactor;

    // Aplica restrições do modo 'slowDown'
    if (this.speakingControlMode === 'slowDown') {
         this.video.playbackRate = Math.min(this.video.playbackRate, 0.85);
    }

    this.updateRangeValue('speed');
}
```

## Versão 4: Controle Focado Apenas na Velocidade da Voz

Esta versão simplifica o código, assumindo que o ajuste de vídeo (`playbackRate`) só deve ocorrer se o modo de controle for especificamente para *slowDown*, e foca a inteligência no `speedControl.value`.

```javascript
adjustSynchronization_V4_VoiceFocus(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const nextSpeechTime = this.speechQueue[0].startTime;
    const timeDifference = nextSpeechTime - currentTime;

    if (Math.abs(timeDifference) < 500) {
        this.speedControl.value = this.userConfiguredSpeed;
        this.video.playbackRate = 1.0;
    } else if (timeDifference < 0) { // Atrasado
        // Prioriza a correção máxima da fala
        this.speedControl.value = parseFloat(this.maxSpeedControl.value); 
    } else { // Adiantado
        // Prioriza a correção para o padrão
        this.speedControl.value = 1.0; 
    }

    // Lógica de vídeo isolada e condicional
    if (this.speakingControlMode === 'slowDown' && Math.abs(timeDifference) > 300) {
        if (timeDifference < 0) {
             this.video.playbackRate = Math.min(this.video.playbackRate + 0.05, 0.85);
        } else {
             this.video.playbackRate = Math.max(this.video.playbackRate - 0.05, 1.0); // Importante: descer do 1.0 se estiver adiantado
        }
    } else {
        // Reset automático do vídeo se o controle de fala não estiver ativado
        this.video.playbackRate = 1.0;
    }

    this.updateRangeValue('speed');
}
```

## Versão 5: Estrutura Baseada em Enum/Estado (Orientada a Objetos)

Esta versão refatora a lógica complexa em estados definidos, tornando o fluxo mais previsível. (Requer a definição de um `enum` ou constantes).

```javascript
// Assumindo que existam: STATUS_SYNCHRONIZED, STATUS_LATE, STATUS_EARLY
adjustSynchronization_V5_StateMachine(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const nextSpeechTime = this.speechQueue[0].startTime;
    const timeDifference = nextSpeechTime - currentTime;
    let currentState;

    if (Math.abs(timeDifference) <= 500) {
        currentState = 'SYNCHRONIZED';
    } else if (timeDifference < 0) {
        currentState = 'LATE';
    } else {
        currentState = 'EARLY';
    }

    switch (currentState) {
        case 'SYNCHRONIZED':
            this.speedControl.value = this.userConfiguredSpeed;
            this.video.playbackRate = 1.0;
            break;

        case 'LATE': // Precisa acelerar
            this.speedControl.value = parseFloat(this.maxSpeedControl.value);
            if (this.speakingControlMode === 'slowDown') {
                // Acelera o vídeo, limitado ao máximo de desaceleração do modo slowDown (0.85)
                this.video.playbackRate = Math.min(this.video.playbackRate + 0.1, 0.85); 
            }
            break;

        case 'EARLY': // Precisa desacelerar
            this.speedControl.value = 1.2; 
            if (this.speakingControlMode === 'slowDown') {
                 // Desacelera o vídeo, limitada ao mínimo de velocidade (1.0, pois 0.85 é o teto do modo)
                this.video.playbackRate = Math.max(this.video.playbackRate - 0.1, 1.0); 
            }
            break;
    }
    this.updateRangeValue('speed');
}
```

## Versão 6: Otimização para Performance (Early Exit)

Esta versão é ideal se este método for chamado em um loop de renderização muito frequente. Ela prioriza sair o mais cedo possível se não houver necessidade de cálculo pesado.

```javascript
adjustSynchronization_V6_Performance(currentTime) {
    // Saída imediata se não estiver em modo avançado ou sem fala na fila
    if (this.dubbingMode !== 'advanced' || this.speechQueue.length === 0) {
        return;
    }

    const nextSpeechTime = this.speechQueue[0].startTime;
    const timeDifference = nextSpeechTime - currentTime;

    // Saída imediata se a sincronia estiver dentro de uma janela de aceitação mínima
    if (Math.abs(timeDifference) < 150) {
        this.speedControl.value = this.userConfiguredSpeed;
        this.video.playbackRate = 1.0;
        return; // Exit early
    }

    // Se passamos dos limites, procedemos com os ajustes
    const maxSpeed = parseFloat(this.maxSpeedControl.value);

    if (timeDifference < 0) { // Atraso
        this.speedControl.value = maxSpeed;
        if (this.speakingControlMode === 'slowDown') {
            this.video.playbackRate = Math.min(this.video.playbackRate + 0.08, 0.85);
        }
    } else { // Adiantamento
        this.speedControl.value = 1.0;
        if (this.speakingControlMode === 'slowDown') {
            this.video.playbackRate = Math.max(this.video.playbackRate - 0.08, 1.0);
        }
    }

    this.updateRangeValue('speed');
}
```

## Versão 7: Controle de "Feedback Loop" (Evitando Oscilação)

Este é um ajuste avançado para evitar que o código fique "corrrendo" de um lado para o outro (overshooting). Se a correção for muito grande, ele "pula" para um estado intermediário mais estável.

```javascript
adjustSynchronization_V7_AntiOscillation(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const nextSpeechTime = this.speechQueue[0].startTime;
    const timeDifference = nextSpeechTime - currentTime;

    // 1. Determina o ajuste bruto
    let grossAdjustment = 0;
    let targetSpeed = this.userConfiguredSpeed;

    if (Math.abs(timeDifference) > 500) {
        if (timeDifference < 0) { // Atraso
            grossAdjustment = parseFloat(this.maxSpeedControl.value) - this.speedControl.value;
            targetSpeed = parseFloat(this.maxSpeedControl.value);
        } else { // Adiantamento
            grossAdjustment = 1.0 - this.speedControl.value;
            targetSpeed = 1.0;
        }
    }

    // 2. Aplica o fator anti-oscilação (Limitando o salto máximo em um único passo)
    const stabilizationFactor = 0.3; 
    const finalAdjustment = Math.sign(grossAdjustment) * Math.min(Math.abs(grossAdjustment), Math.abs(grossAdjustment) * stabilizationFactor);

    // 3. Aplica a velocidade
    this.speedControl.value = this.speedControl.value + finalAdjustment;

    // 4. Gerencia o vídeo
    if (this.speakingControlMode === 'slowDown' && Math.abs(timeDifference) > 300) {
         if (timeDifference < 0) {
             this.video.playbackRate = Math.min(this.video.playbackRate + 0.05, 0.85);
         } else {
             this.video.playbackRate = Math.max(this.video.playbackRate - 0.05, 1.0);
         }
    } else {
        this.video.playbackRate = 1.0;
    }

    this.updateRangeValue('speed');
}
```

## Versão 8: Abordagem Baseada em Percentual de Erro (KPI Driven)

Define o erro percentual ($\frac{\text{Diferença}}{\text{Tempo Esperado}}$) e usa esse percentual para dimensionar os ajustes, o que é ótimo para sistemas que podem ter taxas de fala variadas.

```javascript
adjustSynchronization_V8_ErrorPercentage(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const nextSpeechTime = this.speechQueue[0].startTime;
    const timeDifferenceMs = nextSpeechTime - currentTime;

    // Definimos um "tempo alvo" para a fala, digamos 1 segundo (1000ms)
    const targetDuration = 1000; 

    // O erro é o desvio em relação ao tempo alvo
    const errorRatio = timeDifferenceMs / targetDuration; 

    // Limiares de aceitação baseados na razão de erro
    if (Math.abs(errorRatio) < 0.1) { // Menos de 10% de erro
        this.speedControl.value = this.userConfiguredSpeed;
        this.video.playbackRate = 1.0;
        return;
    }

    const maxSpeed = parseFloat(this.maxSpeedControl.value);

    if (errorRatio < 0) { // Atrasado (Ratio negativo)
        // Ajusta a velocidade proporcionalmente ao erro (ex: erro -0.3 -> velocidade 1.3x)
        this.speedControl.value = Math.min(maxSpeed, 1.0 + Math.abs(errorRatio) * 3); 
    } else { // Adiantado (Ratio positivo)
        this.speedControl.value = 1.0 / (1.0 + errorRatio * 3); // Desaceleração inversa
    }

    // Ajuste do vídeo se necessário
    if (this.speakingControlMode === 'slowDown') {
         this.video.playbackRate = Math.max(0.6, Math.min(0.85, 1.0 - errorRatio * 0.1));
    } else {
        this.video.playbackRate = 1.0;
    }

    this.updateRangeValue('speed');
}
```

## Versão 9: Simplificação Radical (Para Teste Rápido)

Se o objetivo é apenas substituir o código antigo por algo mais limpo, sem a complexidade dos ajustes finos, mas mantendo a estrutura.

